1. import { getUserAgent } from "universal-user-agent";
2. import { request } from "@octokit/request";
3. 
4. import { auth } from "./auth";
5. import { hook } from "./hook";
6. import { StrategyOptions, AuthOptions, Authentication } from "./types";
7. import { VERSION } from "./version";
8. 
9. export type Types = {
10.   StrategyOptions: StrategyOptions;
11.   AuthOptions: AuthOptions;
12.   Authentication: Authentication;
13. };
14. 
15. export function createOAuthAppAuth(options: StrategyOptions) {
16.   const state = Object.assign(
17.     {
18.       request: request.defaults({
19.         headers: {
20.           "user-agent": `octokit-auth-oauth-app.js/${VERSION} ${getUserAgent()}`
21.         }
22.       })
23.     },
24.     options
